#!/usr/bin/env python3
"""Archive existing log/XML records for explicitly scoped Bazel console targets."""

import argparse
import hashlib
import json
import os
import re
import stat
import subprocess
import sys
import tempfile
from pathlib import Path


# A deliberately small acceptance-evidence scope, not an extra test selection.
RETAINED_TARGETS = (
    "//codex-rs/tui:tui-unit-tests",
    "//codex-rs/windows-sandbox-rs:windows-sandbox-rs-unit-tests",
    "//codex-rs/ext/queue:queue-queue_service-test",
    "//codex-rs/app-server:app-server-all-test",
    "//codex-rs/app-server:app-server-unit-tests",
    "//codex-rs/app-server:app-server-all-wine-exec-test",
    "//codex-rs/codex-mcp:codex-mcp-unit-tests",
    "//codex-rs/core:core-unit-tests",
    "//codex-rs/core:core-all-test",
    "//codex-rs/core:core-all-wine-exec-test",
    "//codex-rs/hepta-agentd:hepta-agentd-cognitive-write-qualification-test",
)


def retention_plan(console: Path) -> dict:
    data = console.read_bytes()
    reports = {target: [] for target in RETAINED_TARGETS}
    pattern = re.compile(
        r"^(//\S+)\s+(?:(\(cached\))\s+)?"
        r"(PASSED|FLAKY|FAILED|SKIPPED|TIMEOUT|NO STATUS)\b"
    )
    for original in data.decode("utf-8", errors="replace").splitlines():
        line = re.sub(r"\x1b\[[0-9;]*m", "", original).strip()
        match = pattern.match(line)
        if match and match[1] in reports:
            reports[match[1]].append(
                {
                    "status": match[3],
                    "cached_marker": match[2] is not None,
                    "summary_line": line,
                }
            )
    targets = {}
    errors = []
    for target, entries in reports.items():
        outcomes = {(entry["status"], entry["cached_marker"]) for entry in entries}
        status, cached = next(iter(outcomes)) if len(outcomes) == 1 else (None, None)
        if len(outcomes) > 1:
            errors.append(
                {
                    "target": target,
                    "path": "console summary",
                    "error": "Conflicting summaries; existing logs were not selected",
                }
            )
        targets[target] = {
            "status": status or ("AMBIGUOUS" if entries else "NOT_REPORTED"),
            "cached_marker": cached,
            "summary_lines": [entry["summary_line"] for entry in entries],
            "collect_existing_logs": status in ("PASSED", "FLAKY"),
        }
    return {
        "console_sha256": hashlib.sha256(data).hexdigest(),
        "console_bytes": len(data),
        "targets": targets,
        "selection_errors": errors,
        "limitations": (
            "NOT_REPORTED does not mean filtered or skipped. An absent cached marker "
            "does not prove local execution or an independent remote execution. "
            "Files are existing local records for a console-reported target; their "
            "binding to this invocation is not independently established. "
            "Bazel config expansion and per-case filtering must be checked separately. "
            "Checkout identity is recorded at collection time, not at test start."
        ),
    }


def target_path(label: str) -> Path:
    if not label.startswith("//") or "\\" in label:
        raise ValueError("expected a canonical //package:target label")
    package, separator, name = label[2:].partition(":")
    parts = (package.split("/") if package else []) + name.split("/")
    if not separator or any(
        part in ("", ".", "..")
        or ":" in part
        or any(ord(character) < 32 or ord(character) == 127 for character in part)
        for part in parts
    ):
        raise ValueError("unsafe or non-canonical target path")
    return Path(*parts)


def collect(
    testlogs: Path, output: Path, targets: list[str], *, retention: dict | None = None
) -> tuple[Path, bool]:
    archive_root = output / (
        "selected-target-test-logs" if retention is not None else "failed-test-logs"
    )
    archive_root.mkdir(parents=True, exist_ok=True)
    archive = Path(tempfile.mkdtemp(prefix="invocation-", dir=archive_root))
    manifest = {
        "schema": "bazel_failed_test_logs_v1",
        "scope": (
            "Existing test.log/test.xml and test_attempts log/XML files under "
            "console-selected failed targets only; not a complete suite inventory."
        ),
        "selected_targets": targets,
        "source": {},
        "files": [],
        "errors": [],
    }

    if retention is not None:
        manifest.update(
            schema="bazel_selected_target_logs_v1",
            scope=(
                "Existing local test.log/test.xml and test_attempts log/XML records "
                "for the allowlisted targets reported PASSED or FLAKY in this console; "
                "not failed-target-only evidence or a complete case/attempt inventory."
            ),
            retention=retention,
            complete_case_inventory=False,
        )
        manifest["errors"].extend(retention["selection_errors"])

    def record_error(target: str | None, path: str, error: Exception) -> None:
        manifest["errors"].append(
            {
                "target": target,
                "path": path,
                "error": f"{type(error).__name__}: {error}",
            }
        )

    try:
        revision = subprocess.run(
            ["git", "rev-parse", "HEAD", "HEAD^{tree}"],
            check=True,
            capture_output=True,
            text=True,
            timeout=10,
        ).stdout.splitlines()
        dirty = subprocess.run(
            ["git", "diff", "--quiet", "HEAD", "--"],
            check=False,
            capture_output=True,
            timeout=10,
        )
        if len(revision) != 2 or dirty.returncode not in (0, 1):
            raise ValueError("could not identify the checked-out Git source")
        manifest["source"] = {
            "commit": revision[0],
            "tree": revision[1],
            "tracked_worktree_dirty": dirty.returncode == 1,
        }
    except (OSError, ValueError, subprocess.SubprocessError) as error:
        record_error(None, "git source", error)

    # Bazel's top-level bazel-testlogs entry may itself be a symlink.
    try:
        root = testlogs.resolve(strict=True)
        if not root.is_dir():
            raise ValueError("testlogs root is not a directory")
    except (OSError, ValueError, RuntimeError) as error:
        record_error(None, "testlogs root", error)
        root = None

    if root is not None:
        for index, target in enumerate(targets):
            previous_count = len(manifest["files"])
            try:
                relative_target = target_path(target)
                directory = root / relative_target
                resolved = directory.resolve(strict=True)
                if not resolved.is_relative_to(root):
                    raise ValueError("target directory escapes the testlogs root")
                if not resolved.is_dir():
                    raise ValueError("target path is not a directory")

                def walk_error(error: OSError) -> None:
                    record_error(target, str(relative_target), error)

                for current, directories, filenames in os.walk(
                    directory, followlinks=False, onerror=walk_error
                ):
                    directories.sort()
                    current_path = Path(current)
                    for name in list(directories):
                        child = current_path / name
                        relative = child.relative_to(root)
                        if name in (
                            "test.outputs",
                            "test.outputs_manifest",
                        ) or name.endswith(".runfiles"):
                            directories.remove(name)
                            continue
                        try:
                            if not child.resolve(strict=True).is_relative_to(root):
                                raise ValueError("directory escapes the testlogs root")
                            if child.is_symlink() or getattr(
                                child.lstat(), "st_reparse_tag", 0
                            ):
                                raise ValueError(
                                    "nested linked directory is not traversed"
                                )
                        except (OSError, ValueError, RuntimeError) as error:
                            directories.remove(name)
                            record_error(target, relative.as_posix(), error)

                    for name in sorted(filenames):
                        source = current_path / name
                        target_relative = source.relative_to(directory)
                        if name not in ("test.log", "test.xml") and not (
                            "test_attempts" in target_relative.parts
                            and source.suffix in (".log", ".xml")
                        ):
                            continue
                        relative = source.relative_to(root)
                        destination = (
                            archive / "targets" / f"{index:04d}" / target_relative
                        )
                        try:
                            resolved = source.resolve(strict=True)
                            if not resolved.is_relative_to(root):
                                raise ValueError("file escapes the testlogs root")
                            if not stat.S_ISREG(resolved.stat().st_mode):
                                raise ValueError("log is not a regular file")
                            destination.parent.mkdir(parents=True, exist_ok=True)
                            digest = hashlib.sha256()
                            size = 0
                            with (
                                resolved.open("rb") as reader,
                                destination.open("xb") as writer,
                            ):
                                before = os.fstat(reader.fileno())
                                while chunk := reader.read(1024 * 1024):
                                    writer.write(chunk)
                                    digest.update(chunk)
                                    size += len(chunk)
                                after = os.fstat(reader.fileno())
                            if (
                                size != before.st_size
                                or before.st_size != after.st_size
                                or before.st_mtime_ns != after.st_mtime_ns
                            ):
                                raise ValueError(
                                    "source log changed while being archived"
                                )
                            provenance = (
                                {"source_mtime_ns": before.st_mtime_ns}
                                if retention is not None
                                else {}
                            )
                            manifest["files"].append(
                                {
                                    **provenance,
                                    "target": target,
                                    "testlogs_relative_path": relative.as_posix(),
                                    "archive_relative_path": destination.relative_to(
                                        archive
                                    ).as_posix(),
                                    "bytes": size,
                                    "sha256": digest.hexdigest(),
                                }
                            )
                        except (OSError, ValueError, RuntimeError) as error:
                            try:
                                destination.unlink(missing_ok=True)
                            except OSError as cleanup_error:
                                record_error(target, relative.as_posix(), cleanup_error)
                            record_error(target, relative.as_posix(), error)
                if len(manifest["files"]) == previous_count:
                    raise ValueError(
                        "no existing test log/XML records found for target"
                    )
            except (OSError, ValueError, RuntimeError) as error:
                record_error(target, target, error)

    manifest["complete_for_selected_targets"] = not manifest["errors"]
    (archive / "manifest.json").write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    return archive, manifest["complete_for_selected_targets"]


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--testlogs-dir", type=Path)
    parser.add_argument("--output-dir", type=Path)
    parser.add_argument("--retention-console", type=Path)
    parser.add_argument("--list-retention-targets", action="store_true")
    parser.add_argument("--invocation-args-file", type=Path)
    args = parser.parse_args()
    if args.list_retention_targets and args.retention_console is None:
        parser.error("--list-retention-targets requires --retention-console")
    if not args.list_retention_targets and (
        args.testlogs_dir is None or args.output_dir is None
    ):
        parser.error("--testlogs-dir and --output-dir are required for collection")
    archive_kind = "Selected-target" if args.retention_console else "Failed-test"
    try:
        retention = (
            retention_plan(args.retention_console) if args.retention_console else None
        )
        if args.list_retention_targets:
            for target, report in retention["targets"].items():
                if report["summary_lines"]:
                    print(target)
            return 0
        if retention is None:
            targets = list(
                dict.fromkeys(line.rstrip("\r\n") for line in sys.stdin if line.strip())
            )
        else:
            targets = [
                target
                for target, report in retention["targets"].items()
                if report["collect_existing_logs"]
            ]
            if args.invocation_args_file is not None:
                arguments = (
                    args.invocation_args_file.read_bytes().decode("utf-8").split("\0")
                )
                selection_options = {
                    "--config",
                    "--test_filter",
                    "--test_tag_filters",
                    "--build_tag_filters",
                    "--test_lang_filters",
                    "--test_size_filters",
                    "--test_timeout_filters",
                    "--test_timeout",
                    "--test_sharding_strategy",
                    "--runs_per_test",
                    "--flaky_test_attempts",
                    "--cache_test_results",
                    "--nocache_test_results",
                }
                requested = []
                take_next = False
                for argument in arguments:
                    if argument == "--":
                        break
                    if take_next:
                        requested.append(argument)
                        take_next = False
                    elif argument.split("=", 1)[0] in selection_options:
                        requested.append(argument)
                        take_next = "=" not in argument and argument not in (
                            "--cache_test_results",
                            "--nocache_test_results",
                        )
                retention["wrapper_requested_selection_flags"] = requested
        archive, complete = collect(
            args.testlogs_dir, args.output_dir, targets, retention=retention
        )
    except (OSError, UnicodeError, ValueError, RuntimeError) as error:
        print(
            f"{archive_kind}-log archive could not be written: {error}", file=sys.stderr
        )
        return 1
    print(
        f"{archive_kind}-log archive: {archive} (complete_for_selected_targets={complete})"
    )
    return 0 if complete else 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3

import json
import os
import subprocess
import sys
from contextlib import contextmanager
from collections.abc import Mapping
from collections.abc import Sequence
from pathlib import Path
from tempfile import NamedTemporaryFile


OPENAI_REPOSITORY = "openai/codex"
# Remote configurations select cache/BES/download endpoints. Their -rbe forms
# also select the matching remote executor endpoint.
GENERIC_REMOTE_CONFIG = "buildbuddy-generic"
OPENAI_REMOTE_CONFIG = "buildbuddy-openai"
# These CI configurations require remote build execution. The wrapper supplies
# an RBE configuration, which also includes the common `remote` settings.
REMOTE_EXECUTION_CONFIGS = {
    "--config=ci-linux",
    "--config=ci-macos",
    "--config=ci-v8",
    "--config=ci-windows-cross",
}
# A keyless Windows cross build must reconstruct the local half of the split
# declared by `ci-windows-cross`: MSVC executes host-loaded actions while the
# target remains GNU LLVM. The custom test toolchain is required because Bazel
# otherwise insists that a test's execution and target platforms are equal.
LOCAL_WINDOWS_MSVC_EXEC_PLATFORM = "//:windows_x86_64_msvc"
LOCAL_WINDOWS_MSVC_CC_TOOLCHAIN = "//:local_windows_msvc_cc_toolchain"
LOCAL_WINDOWS_GNULLVM_TEST_TOOLCHAIN = "//:windows_gnullvm_tests_on_msvc_host_toolchain"
# Honor either explicit setting so the wrapper never overrides the caller's
# choice when it supplies the CI default below.
REMOTE_REPO_CONTENTS_CACHE_STARTUP_OPTIONS = {
    "--experimental_remote_repo_contents_cache",
    "--noexperimental_remote_repo_contents_cache",
}


def startup_args(args: Sequence[str], env: Mapping[str, str]) -> list[str]:
    """Return shared startup options that are missing from a Bazel invocation.

    Bazel startup options must precede the command, and changing them restarts
    the server and discards its analysis cache. GitHub Actions invokes Bazel
    through several helpers, so normalize their startup options here while
    preserving any explicit choice made by the caller.
    """
    command_idx = next(
        (idx for idx, arg in enumerate(args) if not arg.startswith("-")),
        len(args),
    )
    configured_startup_args = args[:command_idx]
    injected_args = []

    output_user_root = env.get("BAZEL_OUTPUT_USER_ROOT")
    if output_user_root and not any(
        arg.startswith("--output_user_root=") for arg in configured_startup_args
    ):
        injected_args.append(f"--output_user_root={output_user_root}")

    if env.get("GITHUB_ACTIONS") == "true" and not any(
        arg in REMOTE_REPO_CONTENTS_CACHE_STARTUP_OPTIONS
        for arg in configured_startup_args
    ):
        # Work around Bazel 9 overlay materialization failures seen in CI. This
        # disables only the startup-level repo contents cache; keyed runs still
        # use BuildBuddy.
        injected_args.append("--noexperimental_remote_repo_contents_cache")

    return injected_args


# Only authenticated workflow runs executing trusted upstream code may use the
# OpenAI BuildBuddy host. A pull request event without proof that its head is
# in the upstream repository fails closed to the generic host.
def is_trusted_upstream_run(env: Mapping[str, str]) -> bool:
    # `GITHUB_REPOSITORY` is easy to set locally. Requiring GitHub's workflow
    # marker prevents a local command from opting itself into the OpenAI host.
    if (
        env.get("GITHUB_ACTIONS") != "true"
        or env.get("GITHUB_REPOSITORY") != OPENAI_REPOSITORY
    ):
        return False
    # Non-PR workflow runs in `openai/codex` execute upstream refs, so they are
    # trusted. Fork code reaches these workflows only through pull requests.
    if env.get("GITHUB_EVENT_NAME") != "pull_request":
        return True

    event_path = env.get("GITHUB_EVENT_PATH")
    if not event_path:
        return False
    try:
        event = json.loads(Path(event_path).read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return False

    try:
        return event["pull_request"]["head"]["repo"]["fork"] is False
    except (KeyError, TypeError):
        return False


def uses_openai_host(env: Mapping[str, str]) -> bool:
    return bool(env.get("BUILDBUDDY_API_KEY")) and is_trusted_upstream_run(env)


def uses_remote_execution(args: Sequence[str]) -> bool:
    try:
        separator_idx = args.index("--")
    except ValueError:
        separator_idx = len(args)
    return any(arg in REMOTE_EXECUTION_CONFIGS for arg in args[:separator_idx])


def remote_config(args: Sequence[str], env: Mapping[str, str]) -> str | None:
    if not env.get("BUILDBUDDY_API_KEY"):
        return None

    config = OPENAI_REMOTE_CONFIG if uses_openai_host(env) else GENERIC_REMOTE_CONFIG
    if uses_remote_execution(args):
        config += "-rbe"
    return config


def option_contains_value(args: Sequence[str], option: str, value: str) -> bool:
    """Return whether a repeatable Bazel option already contains `value`."""
    for idx, arg in enumerate(args):
        encoded: str | None = None
        if arg == option and idx + 1 < len(args):
            encoded = args[idx + 1]
        elif arg.startswith(f"{option}="):
            encoded = arg.split("=", 1)[1]
        if encoded is not None and value in encoded.split(","):
            return True
    return False


def bazel_args_without_remote_execution(
    args: Sequence[str], env: Mapping[str, str]
) -> list[str]:
    """Remove credentialed RBE configs and select a coherent local Windows ABI.

    The pinned hermetic LLVM toolchain builds GNU Windows target C/C++ inputs,
    while native MSVC Rust targets and host-loaded proc macros must consume
    archives produced by the installed MSVC compiler. A keyless cross request
    therefore pairs an MSVC host/exec platform with a gnullvm target. A native
    MSVC request keeps its MSVC target and receives the same ABI-scoped local
    C/C++ toolchain. Explicit platform choices and arguments after ``--``
    remain owned by the caller.
    """
    try:
        separator_idx = args.index("--")
    except ValueError:
        separator_idx = len(args)

    prefix = list(args[:separator_idx])
    requested_windows_cross = "--config=ci-windows-cross" in prefix
    requested_native_windows_msvc = option_contains_value(
        prefix, "--platforms", "//:windows_x86_64_msvc"
    )
    prefix = [arg for arg in prefix if arg not in REMOTE_EXECUTION_CONFIGS]
    suffix = list(args[separator_idx:])
    if env.get("RUNNER_OS") != "Windows":
        return [*prefix, *suffix]

    command_idx = next(
        (idx for idx, arg in enumerate(prefix) if not arg.startswith("-")),
        None,
    )
    # Queries and administrative commands do not configure build actions.
    # Do not inject CI build options or runtime skip filters into those calls.
    if command_idx is None or prefix[command_idx] not in {
        "build",
        "test",
        "run",
        "coverage",
        "cquery",
        "aquery",
        "info",
    }:
        return [*prefix, *suffix]

    injected_args: list[str] = []
    if "--config=ci-windows" not in prefix and (
        requested_windows_cross
        or not any(arg.startswith("--config=") for arg in prefix)
    ):
        injected_args.append("--config=ci-windows")
    if requested_windows_cross:
        for option, platform in (
            ("--host_platform", "//:local_windows_msvc"),
            ("--platforms", "//:windows_x86_64_gnullvm"),
        ):
            if not any(arg == option or arg.startswith(f"{option}=") for arg in prefix):
                injected_args.append(f"{option}={platform}")
        for option, value in (
            ("--extra_execution_platforms", LOCAL_WINDOWS_MSVC_EXEC_PLATFORM),
            ("--extra_toolchains", LOCAL_WINDOWS_GNULLVM_TEST_TOOLCHAIN),
        ):
            if not option_contains_value(prefix, option, value):
                injected_args.append(f"{option}={value}")

    if requested_windows_cross or requested_native_windows_msvc:
        # Keep native archives on the same ABI as the Rust action that links
        # them. Without this bounded override, globally registered hermetic
        # LLVM can produce MinGW objects for an MSVC Rust target.
        for option, value in (
            ("--extra_toolchains", LOCAL_WINDOWS_MSVC_CC_TOOLCHAIN),
            ("--repo_env", "BAZEL_DO_NOT_DETECT_CPP_TOOLCHAIN=0"),
        ):
            if not option_contains_value(prefix, option, value):
                injected_args.append(f"{option}={value}")

    # Put defaults before caller options so a CI config cannot override an
    # explicit per-job cache path (or other later command-line setting).
    # Later --extra_toolchains also take precedence over the fallback compiler.
    return [
        *prefix[: command_idx + 1],
        *injected_args,
        *prefix[command_idx + 1 :],
        *suffix,
    ]


def bazel_args_with_remote_config(
    args: Sequence[str], env: Mapping[str, str]
) -> list[str]:
    command_idx = next(
        (idx for idx, arg in enumerate(args) if not arg.startswith("-")),
        None,
    )
    if command_idx is None:
        raise ValueError("expected a Bazel command")

    config = remote_config(args, env)
    if config is None or not uses_remote_execution(args):
        # Cache authentication does not change the compiler ABI. Native Windows
        # actions need the same local MSVC toolchain with or without a remote
        # cache; only actual RBE requests keep their remote execution platform.
        configured_args = bazel_args_without_remote_execution(args, env)
    else:
        configured_args = list(args)

    if config is not None:
        # `remote_config()` returns a configuration only when this key is present.
        api_key = env["BUILDBUDDY_API_KEY"]
        remote_args = [
            f"--config={config}",
            f"--remote_header=x-buildbuddy-api-key={api_key}",
        ]

        # Insert immediately after the Bazel command. This keeps wrapper-added
        # options out of positional payloads and lets later CI configs override
        # shared RBE defaults such as the Windows cross-compilation exec platforms.
        configured_args = [
            *configured_args[: command_idx + 1],
            *remote_args,
            *configured_args[command_idx + 1 :],
        ]

    try:
        separator_idx = configured_args.index("--")
    except ValueError:
        separator_idx = len(configured_args)

    cache_args = [
        f"{option_prefix}{env[env_name]}"
        for env_name, option_prefix in (
            ("BAZEL_REPO_CONTENTS_CACHE", "--repo_contents_cache="),
            ("BAZEL_REPOSITORY_CACHE", "--repository_cache="),
        )
        if env.get(env_name)
        and not any(
            arg.startswith(option_prefix) for arg in configured_args[:separator_idx]
        )
    ]
    return [
        *configured_args[:separator_idx],
        *cache_args,
        *configured_args[separator_idx:],
    ]


def bazel_command(*args: str, env: Mapping[str, str] | None = None) -> list[str]:
    env = os.environ if env is None else env
    bazel = env.get("CODEX_BAZEL_BIN", "bazel")
    return [bazel, *startup_args(args, env), *bazel_args_with_remote_config(args, env)]


def invocation_args(args: Sequence[str]) -> list[str]:
    """Decode the shell's lossless transport before resolving Bazel options."""
    if not args or args[0] != "--wrapper-args-file":
        return list(args)
    if len(args) != 2:
        raise ValueError("expected exactly one wrapper argument file")
    encoded = Path(args[1]).read_bytes()
    if not encoded.endswith(b"\0"):
        raise ValueError("wrapper argument file is missing its final delimiter")
    return [arg.decode("utf-8") for arg in encoded[:-1].split(b"\0")]


@contextmanager
def windows_target_patterns(args: Sequence[str], env: Mapping[str, str]):
    """Keep a complete target roster out of the native Bazel command line."""
    command = next((arg for arg in args[1:] if not arg.startswith("-")), None)
    if (
        (os.name != "nt" and env.get("RUNNER_OS") != "Windows")
        or command not in {"build", "test", "coverage"}
        or "--" not in args
    ):
        yield list(args), None
        return
    separator = args.index("--")
    if any(
        arg == "--target_pattern_file" or arg.startswith("--target_pattern_file=")
        for arg in args[:separator]
    ):
        # A caller's pattern file owns its selection semantics. Let Bazel
        # validate combinations with positional patterns instead of replacing
        # that file with a wrapper-generated roster.
        yield list(args), None
        return
    targets = args[separator + 1 :]
    if not targets:
        yield list(args), None
        return
    if any("\n" in target or "\r" in target for target in targets):
        raise ValueError("Bazel target patterns cannot contain line breaks")
    # Bazel reads one UTF-8 pattern per line, including exclusion patterns.
    # Keep the file until the real child retires, even when it reports failure.
    with NamedTemporaryFile(
        mode="w", encoding="utf-8", newline="\n", delete=False
    ) as output:
        path = Path(output.name)
        output.writelines(f"{target}\n" for target in targets)
    try:
        yield [*args[:separator], f"--target_pattern_file={path}"], path
    finally:
        path.unlink()


def main() -> None:
    args = invocation_args(sys.argv[1:])
    config = remote_config(args, os.environ)
    if config is None:
        print(
            "BuildBuddy key unavailable; using local Bazel configuration.",
            file=sys.stderr,
        )
    else:
        host_description = (
            "OpenAI tenant" if uses_openai_host(os.environ) else "generic"
        )
        print(
            f"Using {host_description} BuildBuddy configuration: {config}.",
            file=sys.stderr,
        )

    with windows_target_patterns(bazel_command(*args), os.environ) as (
        command,
        target_file,
    ):
        if os.name == "nt" or target_file is not None:
            # Wait for the real child so its pattern file stays available and
            # its failure status reaches CI without CRT exec argument splitting.
            result = subprocess.run(command, check=False)
            raise SystemExit(result.returncode)

        os.execvp(command[0], command)


if __name__ == "__main__":
    main()
